using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class InventoryGroundTests
    {
        static InvData Data()=>new InvData{Items=new Dictionary<string,int>{{"water",5}},GridSlots=new List<string>{null,"water"},Containers=new Dictionary<string,Dictionary<string,int>>{{"home",new Dictionary<string,int>{{"water",7}}}},Extra=new Dictionary<string,JToken>{{"Future","keep"}}};
        static string Drop(ref InvData d,int quantity=3){Assert.True(InventoryGroundRules.Drop(ref d,"water",quantity,1,2,3,0,n=>{}));return d.GroundItems[d.GroundItems.Count-1].Id;}
        [Fact]public void DropAndPickupRemainOneAtomicSaveWithMetadataAndPosition(){var d=Data();int saves=0;Assert.True(InventoryGroundRules.Drop(ref d,"water",3,1,2,3,42,n=>{saves++;Assert.Equal(2,n.Items["water"]);Assert.Single(n.GroundItems);}));Assert.Equal(1,saves);var row=d.GroundItems[0];Assert.Equal(42,row.Interior);Assert.Equal(3,row.Z);row.Extra=new Dictionary<string,JToken>{{"FutureDrop",true}};d=JsonConvert.DeserializeObject<InvData>(JsonConvert.SerializeObject(d));Assert.True(InventoryGroundRules.Pickup(ref d,row.Id,1,30,_=>.5f,n=>saves++));Assert.Equal(3,d.Items["water"]);Assert.Equal(2,d.GroundItems[0].Quantity);Assert.True((bool)d.GroundItems[0].Extra["FutureDrop"]);Assert.Equal(7,d.Containers["home"]["water"]);Assert.Equal("water",d.GridSlots[1]);Assert.Equal("keep",(string)d.Extra["Future"]);}
        [Fact]public void DropSaveFailureLeavesEntireOriginalUnchanged(){var d=Data();var original=d;string before=JsonConvert.SerializeObject(d);Assert.Throws<IOException>(()=>InventoryGroundRules.Drop(ref d,"water",5,1,2,3,0,n=>throw new IOException()));Assert.Same(original,d);Assert.Equal(before,JsonConvert.SerializeObject(d));}
        [Fact]public void PickupSaveFailureKeepsGroundAndInventoryForRetry(){var d=Data();string id=Drop(ref d);string before=JsonConvert.SerializeObject(d);Assert.Throws<IOException>(()=>InventoryGroundRules.Pickup(ref d,id,3,30,_=>.5f,n=>throw new IOException()));Assert.Equal(before,JsonConvert.SerializeObject(d));Assert.True(InventoryGroundRules.Pickup(ref d,id,3,30,_=>.5f,n=>{}));Assert.Empty(d.GroundItems);Assert.Equal(5,d.Items["water"]);Assert.False(InventoryGroundRules.Pickup(ref d,id,3,30,_=>.5f,n=>throw new Exception()));}
        [Theory][InlineData(0)][InlineData(-1)][InlineData(6)]public void InvalidQuantityDoesNotSave(int count){var d=Data();Assert.False(InventoryGroundRules.Drop(ref d,"water",count,1,2,3,0,n=>throw new Exception()));Assert.Null(d.GroundItems);}
        [Theory][InlineData(float.NaN)][InlineData(float.PositiveInfinity)][InlineData(100000)]public void InvalidCoordinatesDoNotRemoveItems(float x){var d=Data();Assert.False(InventoryGroundRules.Drop(ref d,"water",1,x,2,3,0,n=>throw new Exception()));Assert.Equal(5,d.Items["water"]);}
        [Fact]public void NegativeInteriorRejected(){var d=Data();Assert.False(InventoryGroundRules.Drop(ref d,"water",1,1,2,3,-1,n=>throw new Exception()));}
        [Fact]public void NearestRequiresMatchingInteriorAndActualThreeDimensionalRange(){var d=Data();string id=Drop(ref d);Assert.Null(InventoryGroundRules.Nearest(d,1,2,3,1,2));Assert.Null(InventoryGroundRules.Nearest(d,1,2,6,0,2));Assert.Equal(id,InventoryGroundRules.Nearest(d,1,2,4.8f,0,1.8f).Id);}
        [Fact]public void PartialPickupHonorsCapacityAndRetainsRemainder(){var d=Data();string id=Drop(ref d);Assert.Equal(1,InventoryGroundRules.Fits(d,id,1.5,_=>.5f));Assert.False(InventoryGroundRules.Pickup(ref d,id,2,1.5,_=>.5f,n=>throw new Exception()));Assert.True(InventoryGroundRules.Pickup(ref d,id,1,1.5,_=>.5f,n=>{}));Assert.Equal(2,d.GroundItems[0].Quantity);Assert.Equal(0,InventoryGroundRules.Fits(d,id,1.5,_=>.5f));}
        [Fact]public void MissingDefinitionCanBeRoundtrippedWithoutDiscardingRecord(){var d=Data();string id=Drop(ref d);d.GroundItems[0].Item="custom-unknown";var restored=JsonConvert.DeserializeObject<InvData>(JsonConvert.SerializeObject(d));Assert.Equal(id,restored.GroundItems[0].Id);Assert.Equal("custom-unknown",restored.GroundItems[0].Item);Assert.True(InventoryGroundRules.Valid(restored));}
        [Fact]public void OverweightCannotRecoverMore(){var d=Data();string id=Drop(ref d,1);Assert.Equal(0,InventoryGroundRules.Fits(d,id,1,_=>.5f));}
        [Fact]public void ZeroWeightPickupStillCannotOverflowCounters(){var d=Data();string id=Drop(ref d);d.Items["water"]=int.MaxValue;Assert.Equal(0,InventoryGroundRules.Fits(d,id,30,_=>0));}
        [Theory][InlineData(float.NaN)][InlineData(float.PositiveInfinity)][InlineData(-1)]public void InvalidWeightsCannotMintItems(float weight){var d=Data();string id=Drop(ref d);Assert.Equal(0,InventoryGroundRules.Fits(d,id,30,_=>weight));}
        [Theory][InlineData(double.NaN)][InlineData(double.PositiveInfinity)][InlineData(-1)][InlineData(0)]public void InvalidCapacityRejectsPickup(double capacity){var d=Data();string id=Drop(ref d);Assert.False(InventoryGroundRules.Pickup(ref d,id,1,capacity,_=>.5f,n=>throw new Exception()));}
        [Fact]public void GroundLimitNeverDeletesOlderPiles(){var d=Data();d.Items["water"]=129;for(int i=0;i<128;i++)Drop(ref d,1);Assert.False(InventoryGroundRules.Drop(ref d,"water",1,1,2,3,0,n=>throw new Exception()));Assert.Equal(128,d.GroundItems.Count);Assert.Equal(1,d.Items["water"]);}
        [Fact]public void DuplicateOrMalformedGroundRecordsBlockEditsPreservingOriginal(){var d=Data();string id=Drop(ref d);d.GroundItems.Add(new InventoryGroundItem{Id=id,Item="water",Quantity=1,X=1,Y=2,Z=3});Assert.False(InventoryGroundRules.Valid(d));string before=JsonConvert.SerializeObject(d);Assert.False(InventoryGroundRules.Pickup(ref d,id,1,30,_=>.5f,n=>throw new Exception()));Assert.Equal(before,JsonConvert.SerializeObject(d));d.GroundItems[1]=null;Assert.False(InventoryGroundRules.Drop(ref d,"water",1,1,2,3,0,n=>throw new Exception()));}
        [Fact]public void DroppedGunMetadataSurvivesAndNativeObservationCannotCloneIt(){var d=Data();var row=new CharacterWeapon{Hash=1,AmmoType=10,Tint=2,Clip=12,Components=new List<CharacterAttachment>{new CharacterAttachment{Hash=90,Tint=-1}}};InventoryArmoryRules.Import(ref d,new[]{new ArmoryObservation{Weapon=row,Ammo=40}},n=>{});string item=InventoryArmoryRules.WeaponId(1);Assert.True(InventoryGroundRules.Drop(ref d,item,1,1,2,3,0,n=>{}));Assert.False(InventoryArmoryRules.CanReacquire(d,item));Assert.Equal(12,d.Armory.Weapons[item].Clip);Assert.True(InventoryGroundRules.Pickup(ref d,d.GroundItems[0].Id,1,30,_=>.1f,n=>{}));Assert.Equal(90,d.Armory.Weapons[item].Components[0].Hash);Assert.Equal(40,d.Items[InventoryArmoryRules.AmmoId(10)]);}
        [Fact]public void GroundQuantitiesNeverContributeToPersonalWeight(){var d=Data();double before=InventoryBurdenRules.Total(d.Items,_=>.5f);Drop(ref d,5);Assert.Equal(2.5,before);Assert.Equal(0,InventoryBurdenRules.Total(d.Items,_=>.5f));}
        [Fact]public void ProfilesKeepIndependentGroundRecords(){var a=Data();var b=Data();string id=Drop(ref a);Assert.Null(b.GroundItems);Assert.False(InventoryGroundRules.Pickup(ref b,id,1,30,_=>.5f,n=>throw new Exception()));}
    }
    public class InventoryInputTests
    {
        [Fact]public void WheelPolicyRequiresNoArmoryOrActivityState()=>Assert.True(InventoryInputRules.BlockWheel(true,true,true,false,false,false,false,false,true));
        [Theory][InlineData("disabled")][InlineData("human")][InlineData("dead")][InlineData("vehicle")][InlineData("boarding")][InlineData("pause")][InlineData("mission")][InlineData("cutscene")][InlineData("control")]
        public void NativeProtectedContextsArePreserved(string reason)=>Assert.False(InventoryInputRules.BlockWheel(reason!="disabled",reason!="human",reason!="dead",reason=="vehicle",reason=="boarding",reason=="pause",reason=="mission",reason=="cutscene",reason!="control"));
    }
}
